export interface Park {
  id: string
  name: string
  description?: string | null
  location?: {
    lat?: number | null
    lng?: number | null
    address?: string | null
  } | null
  amenities?: string[] | null
  hours?: string | null
  images?: string[] | null
  acreage?: number | null
  rating?: number | null
}

export interface ParkSelectionProps {
  parks: readonly Park[]
  selectedParkId: string | null
  onSelectPark: (id: string) => void
}

import type { Park } from '../../types'

interface ParkDetailsProps {
  park: Park | undefined
  onClose: () => void
}

export function ParkDetails({ park }: ParkDetailsProps) {
  return (
    <section className="panel" aria-labelledby="park-details-heading">
      <h2 id="park-details-heading">Park details</h2>
      <p>{park ? `Details placeholder for ${park.name}.` : 'Details placeholder. No park selected.'}</p>
    </section>
  )
}

// @vitest-environment jsdom
import { render, screen, within } from '@testing-library/react'
import { expect, it } from 'vitest'
import App from './App'
import sample from './data/parks.sample.json'

it('renders the three named regions with the full sample and no initial selection', () => {
  render(<App />)
  const list = screen.getByRole('region', { name: 'Park list' })
  expect(within(list).getByText(`List placeholder for ${sample.length} parks.`)).toBeTruthy()
  const details = screen.getByRole('region', { name: 'Park details' })
  expect(within(details).getByText(/no park selected/i)).toBeTruthy()
  expect(screen.getByRole('region', { name: 'Park map' })).toBeTruthy()
})

import { useState } from 'react'
import { ParkDetails } from './components/ParkDetails/ParkDetails'
import { ParkList } from './components/ParkList/ParkList'
import { ParkMap } from './components/ParkMap/ParkMap'
import { normalizePark } from './data/normalizePark'
import sample from './data/parks.sample.json'

const parks = sample.map(normalizePark)

export default function App() {
  const [selectedParkId, setSelectedParkId] = useState<string | null>(null)
  const selectedPark = parks.find((park) => park.id === selectedParkId)
  const selectionProps = { parks, selectedParkId, onSelectPark: setSelectedParkId }

  return (
    <main>
      <h1>Find a Park</h1>
      <div className="park-layout">
        <div className="park-sidebar">
          <ParkList {...selectionProps} />
          <ParkDetails park={selectedPark} onClose={() => setSelectedParkId(null)} />
        </div>
        <ParkMap {...selectionProps} />
      </div>
    </main>
  )
}

:root {
  font-family: system-ui, sans-serif;
  color: #1c3529;
  background: #f6f8f5;
  line-height: 1.5;
}

* { box-sizing: border-box; }
body { margin: 0; }
main { max-width: 76rem; margin: 0 auto; padding: clamp(1rem, 4vw, 3rem); }
h1 { margin: 0 0 1.25rem; font-size: clamp(2rem, 4vw, 3rem); }
h2 { margin: 0; font-size: 1.25rem; }
p { margin: 0.5rem 0 0; }

.park-layout {
  display: grid;
  grid-template-columns: minmax(0, 2fr) minmax(0, 3fr);
  gap: 1rem;
}

.park-sidebar { display: grid; align-content: start; gap: 1rem; }
.panel { background: white; border: 1px solid #c7d3ca; border-radius: 0.5rem; padding: 1.25rem; }
.map-panel { min-height: 21rem; background: #e5ede6; }
:focus-visible { outline: 3px solid #1853a0; outline-offset: 3px; }

@media (max-width: 44rem) {
  .park-layout { grid-template-columns: minmax(0, 1fr); }
  .map-panel { min-height: 12rem; }
}

import type { Park } from '../types'

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function cleanString(value: unknown) {
  return typeof value === 'string' ? value.trim() || undefined : undefined
}

function stringList(value: unknown): string[] {
  if (!Array.isArray(value)) return []
  return value.map(cleanString).filter((item) => item !== undefined)
}

function finiteNumber(value: unknown) {
  return typeof value === 'number' && Number.isFinite(value) ? value : undefined
}

function coordinate(value: unknown, limit: number) {
  const number = finiteNumber(value)
  return number !== undefined && Math.abs(number) <= limit ? number : undefined
}

function normalizeLocation(value: unknown): Park['location'] {
  if (!isRecord(value)) return undefined
  const lat = coordinate(value.lat, 90)
  const lng = coordinate(value.lng, 180)
  const address = cleanString(value.address)

  // A marker needs the full pair. An address is useful even without it.
  if (lat === undefined || lng === undefined) return address ? { address } : undefined
  return { lat, lng, address }
}

export function normalizePark(raw: unknown): Park {
  if (!isRecord(raw)) throw new Error('Expected a park record')
  const id = cleanString(raw.id)
  const name = cleanString(raw.name)
  if (!id || !name) throw new Error('A park requires an id and name')

  return {
    id,
    name,
    description: cleanString(raw.description),
    location: normalizeLocation(raw.location),
    amenities: stringList(raw.amenities),
    hours: cleanString(raw.hours),
    images: stringList(raw.images),
    acreage: finiteNumber(raw.acreage),
    rating: finiteNumber(raw.rating),
  }
}
